export const CLASS_LABELS_ARSL = ["ain", "alef", "baa", "dad", "dal", "faa", "ghain", "haa", "heh", "jeem", "kaf", "khaa", "lam", "meem", "noon", "qaf", "raa", "sad", "seen", "sheen", "taa", "tah", "thaa", "thal", "waw", "yaa", "zah", "zay"];

// predict_arsl(features): features is the same 42-number array
// landmarksToFeatures() in app.js produces. Returns
// { label, confidence } (confidence is 0-100), or null if the
// model produced no usable score.
export function predict_arsl(features) {
  let scores = score(features);
  if (typeof scores === 'number') {
    // Binary-classifier edge case: m2cgen returns a single
    // probability for the positive (2nd) class instead of an array.
    scores = [1 - scores, scores];
  }
  if (!Array.isArray(scores) || scores.length === 0) return null;
  let best = 0;
  for (let i = 1; i < scores.length; i++) {
    if (scores[i] > scores[best]) best = i;
  }
  const total = scores.reduce((a, b) => a + b, 0) || 1;
  return { label: CLASS_LABELS_ARSL[best], confidence: (scores[best] / total) * 100 };
}
